css:
.loader {
  position: relative;
  width: 50px;
  height: 44px;
}
.loader::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 0;
  width: 3px;
  height: 100%;
  border-radius: 2px;
  background: #4338ca;
}
.loader i {
  position: absolute;
  top: 8px;
  width: 9px;
  height: 22px;
  background: #6366f1;
  animation: rip 0.9s ease-in-out infinite;
}
.loader i:nth-child(1) { left: 8px; animation-delay: 0s; }
.loader i:nth-child(2) { left: 17px; animation-delay: 0.09s; }
.loader i:nth-child(3) { left: 26px; animation-delay: 0.18s; }
.loader i:nth-child(4) { left: 35px; animation-delay: 0.27s; }
@keyframes rip {
  0%, 100% { transform: translateY(0) skewX(0deg); }
  50% { transform: translateY(-4px) skewX(-7deg); }
}
